+fn action_node(
+    core: &mut UnifiedTreeCore<Vec<i64>>,
+    parent: NodeIdx_,
+    key: i64,
+    device: bool,
+    host: bool,
+) -> NodeIdx_ {
+    let node = core.arena.alloc_child(parent, vec![key], 0, None).unwrap();
+    if device {
+        core.arena
+            .set_device_value(node, FULL, Tensor::from_slice(&[key]));
+        core.inc_evictable_size(FULL, 1);
+    }
