+        assert_eq!(consumed_from, window_start);
+        assert_eq!(tc.arena.node(leaf).id, original_id);
+        assert_eq!(tc.arena.node(leaf).device_lock_ref(FULL), 0);
+        let [
+            CacheAction::RecoverSwaWithLockedFull {
+                node_id,
+                kept_full,
+                incoming_full,
